/* prog53_dfs_cycle.c
 *
 * Re‑implementation of the original binary (prog53_dfs_cycle).
 * The program reads a list of directed edges from the command line,
 * builds a graph on at most 8 vertices (0 … 7) and reports whether
 * the graph contains a directed cycle.
 *
 *   $ ./prog53_dfs_cycle 0 1 1 2 2 0
 *   CYCLE
 *
 *   $ ./prog53_dfs_cycle 0 1 1 2 2 3
 *   ACYCLIC
 *
 * If the input is malformed (odd number of arguments, non‑numeric
 * arguments, or vertex numbers outside the range 0‑7) the program
 * prints “INVALID_INPUT”.
 *
 * The implementation follows the logic that was recovered from the
 * decompiled, heavily obfuscated binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

#define MAXV 8               /* maximum number of vertices */
#define INVALID_INPUT_MSG "INVALID_INPUT"
#define CYCLE_MSG          "CYCLE"
#define ACYCLIC_MSG        "ACYCLIC"

/* adjacency matrix: adj[u][v] == 1 if there is an edge u → v */
static int adj[MAXV][MAXV];
/* colour array used by DFS: 0 = unvisited, 1 = visiting, 2 = visited */
static int colour[MAXV];
static int found_cycle = 0;

/* Utility: check whether a string represents a non‑negative integer. */
static int is_non_negative_int(const char *s)
{
    if (*s == '\0')
        return 0;
    while (*s) {
        if (!isdigit((unsigned char)*s))
            return 0;
        ++s;
    }
    return 1;
}

/* Depth‑first search that detects a directed cycle. */
static void dfs(int u)
{
    if (found_cycle)
        return;               /* early exit if a cycle is already found */

    colour[u] = 1;           /* mark as visiting */

    for (int v = 0; v < MAXV; ++v) {
        if (!adj[u][v])
            continue;        /* no edge u → v */

        if (colour[v] == 0) {
            dfs(v);
            if (found_cycle)
                return;
        } else if (colour[v] == 1) {
            /* back edge → cycle */
            found_cycle = 1;
            return;
        }
    }

    colour[u] = 2;           /* mark as visited */
}

int main(int argc, char *argv[])
{
    /* 1. Validate the number of arguments.
     *    After the program name we expect an even number of arguments,
     *    each pair representing one directed edge. */
    if ((argc - 1) % 2 != 0) {
        puts(INVALID_INPUT_MSG);
        return 0;
    }

    /* 2. Parse all edge arguments, checking that they are valid
     *    non‑negative integers and lie in the range [0,7]. */
    int edge_cnt = (argc - 1) / 2;
    for (int i = 0; i < edge_cnt; ++i) {
        const char *src_str = argv[1 + i * 2];
        const char *dst_str = argv[1 + i * 2 + 1];

        if (!is_non_negative_int(src_str) || !is_non_negative_int(dst_str)) {
            puts(INVALID_INPUT_MSG);
            return 0;
        }

        long src = strtol(src_str, NULL, 10);
        long dst = strtol(dst_str, NULL, 10);

        if (src < 0 || src >= MAXV || dst < 0 || dst >= MAXV) {
            puts(INVALID_INPUT_MSG);
            return 0;
        }

        adj[(int)src][(int)dst] = 1;   /* directed edge */
    }

    /* 3. Run DFS from every unvisited vertex to detect a cycle. */
    for (int v = 0; v < MAXV; ++v) {
        if (colour[v] == 0) {
            dfs(v);
            if (found_cycle)
                break;
        }
    }

    /* 4. Output the result. */
    puts(found_cycle ? CYCLE_MSG : ACYCLIC_MSG);
    return 0;
}
